import crypto from "node:crypto";
import { ticketStore } from "./lib.mjs";
import { NATIONAL_SITE_ID, NATIONAL_SITE_LABEL, allTicketRows, auditRow, columnFor, doneAt, isOverdue, ticketAccess } from "./tickets.mjs";

/**
 * Support tickets on the work TV. The Truckies Lounge TV page itself is public and has no token, but tickets are internal, so this
 * feed is behind one read-only "TV link" key:
 *   - the key is generated by the admin (Support > Settings > TV link), shown once, and only its SHA-256 hash is stored (key "tv-link");
 *   - the TV endpoint compares hashes in constant time and returns a small, sanitised, read-only payload (no emails, phones, descriptions,
 *     messages, files, assignees or visitor data);
 *   - replacing the key switches the old link off immediately; turning it off removes the hash.
 */
export const TV_DONE_WINDOW_MS = 24 * 3600 * 1000;
export const TV_MAX_TICKETS = 60;
const COLUMN_ORDER = ["submitted", "needs-info", "in-progress", "done"];
const PRIORITY_RANK = { urgent: 0, high: 1, normal: 2, low: 3 };
const QUEUE_LABEL = { screens: "Screens", signage: "Signage" };

const hashKey = (key) => crypto.createHash("sha256").update(String(key || ""), "utf8").digest();

export async function tvLinkStatus() {
  const row = await ticketStore().get("tv-link", { type: "json" }).catch(() => null);
  return row?.hash ? { configured: true, createdAt: row.createdAt || "", createdBy: row.createdBy || "" } : { configured: false };
}

async function adminOnly(actor) {
  const access = await ticketAccess(actor);
  return access.role === "admin" ? access : null;
}

/** Make (or replace) the TV link key. The plain key is returned once and never stored. */
export async function createTvLink(actor, at = Date.now()) {
  const access = await adminOnly(actor);
  if (!access) return { status: 403, error: "The TV link is limited to the ticket admin." };
  const key = crypto.randomBytes(32).toString("base64url");
  await ticketStore().setJSON("tv-link", { hash: hashKey(key).toString("hex"), createdAt: new Date(at).toISOString(), createdBy: access.email });
  await auditRow(access.email, "tv-link", "", "created or replaced");
  return { status: 200, body: { key, createdAt: new Date(at).toISOString() } };
}

export async function removeTvLink(actor) {
  const access = await adminOnly(actor);
  if (!access) return { status: 403, error: "The TV link is limited to the ticket admin." };
  await ticketStore().delete("tv-link").catch(() => null);
  await auditRow(access.email, "tv-link", "", "turned off");
  return { status: 200, body: { configured: false } };
}

/** True only for the current key. Constant-time on the hashes, so nothing is learned from timing. */
export async function verifyTvKey(key) {
  const text = String(key || "");
  if (!text || text.length > 200) return false;
  const row = await ticketStore().get("tv-link", { type: "json" }).catch(() => null);
  if (!row?.hash || !/^[a-f0-9]{64}$/.test(row.hash)) return false;
  return crypto.timingSafeEqual(hashKey(text), Buffer.from(row.hash, "hex"));
}

/** Keep a headline useful on a wall screen without leaking contact details that were typed into the subject. */
export function cleanSubject(value) {
  let text = String(value || "").replace(/\s+/g, " ").trim();
  text = text.replace(/[^\s@]+@[^\s@]+\.[^\s@]+/g, "(email removed)").replace(/\+?\d[\d\s().-]{7,}\d/g, "(number removed)");
  return text.length > 90 ? text.slice(0, 89).trimEnd() + "…" : text;
}
export function firstName(value) {
  const word = String(value || "").trim().split(/\s+/)[0] || "";
  const letters = word.replace(/[^A-Za-z'’-]/g, "").slice(0, 20);
  return /@/.test(word) ? "" : letters;
}
function siteName(ticket) {
  if (ticket.siteId === NATIONAL_SITE_ID) return NATIONAL_SITE_LABEL;
  return String(ticket.siteLabel || "").replace(/\s+/g, " ").trim().slice(0, 40);
}

/** The sanitised, read-only payload. Every field is listed here on purpose. */
export function presentForTv(ticket, at) {
  const column = columnFor(ticket.status);
  const created = Date.parse(ticket.createdAt);
  const out = {
    number: ticket.number,
    subject: cleanSubject(ticket.subject),
    queue: QUEUE_LABEL[ticket.queue] || "",
    column,
    site: siteName(ticket),
    priority: ticket.priority,
    firstName: firstName(ticket.requesterName),
    daysOpen: Number.isFinite(created) ? Math.max(0, Math.floor((at - created) / 86400000)) : 0,
    overdue: isOverdue(ticket, at),
  };
  if (column === "done") {
    const done = Date.parse(doneAt(ticket));
    out.doneHoursAgo = Number.isFinite(done) ? Math.max(0, Math.floor((at - done) / 3600000)) : 0;
  }
  return out;
}

export async function tvTickets(at = Date.now()) {
  const rows = await allTicketRows();
  const shown = rows.filter((ticket) => {
    const column = columnFor(ticket.status);
    if (column !== "done") return true;
    const done = Date.parse(doneAt(ticket));
    return Number.isFinite(done) && at - done <= TV_DONE_WINDOW_MS && at - done >= -60000;
  });
  const items = shown.map((ticket) => ({ ticket, row: presentForTv(ticket, at) })).sort((a, b) => {
    const col = COLUMN_ORDER.indexOf(a.row.column) - COLUMN_ORDER.indexOf(b.row.column);
    if (col) return col;
    if (a.row.overdue !== b.row.overdue) return a.row.overdue ? -1 : 1;
    const pr = (PRIORITY_RANK[a.row.priority] ?? 2) - (PRIORITY_RANK[b.row.priority] ?? 2);
    if (pr) return pr;
    return b.row.daysOpen - a.row.daysOpen;
  });
  const counts = Object.fromEntries(COLUMN_ORDER.map((id) => [id, 0]));
  for (const { row } of items) counts[row.column] += 1;
  return {
    generatedAt: new Date(at).toISOString(),
    counts,
    overdue: items.filter(({ row }) => row.overdue).length,
    truncated: items.length > TV_MAX_TICKETS,
    tickets: items.slice(0, TV_MAX_TICKETS).map(({ row }) => row),
  };
}
